import sys

def min_roads_to_demolish(n, q):
    return (n - q + 1) * (q - 1)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        q = int(data[index + 1])
        index += 2
        results.append(min_roads_to_demolish(n, q))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
